class Solution {
public:
    int numSplits(string s) {
        int n = s.size();
        int rightCount[26] = {0};
        int leftCount[26] = {0};
        int rightDistinct = 0;
        int leftDistinct = 0;
        int result = 0;

        for (char c : s) {
            if (rightCount[c - 'a'] == 0) rightDistinct++;
            rightCount[c - 'a']++;
        }

        for (int i = 0; i < n - 1; i++) {
            int idx = s[i] - 'a';
            if (leftCount[idx] == 0) leftDistinct++;
            leftCount[idx]++;
            rightCount[idx]--;
            if (rightCount[idx] == 0) rightDistinct--;
            if (leftDistinct == rightDistinct) result++;
        }

        return result;
    }
};
